            v(211,1) = qcx*v(106,1) + wqx*v(106,0)
            v(246,1) = qcy*v(71,1) + wqy*v(71,0) &
               + 1.0_dp*oo2e*(v(1,1) - re*v(1,0))
            v(316,1) = qcz*v(106,1) + wqz*v(106,0) &
